import React, { useState } from 'react';
import { useQuery } from 'react-query';
import { 
  FileText, 
  Clock, 
  CheckCircle, 
  XCircle, 
  AlertCircle,
  Eye,
  ExternalLink
} from 'lucide-react';
import axios from 'axios';
import LoadingSpinner from './ui/LoadingSpinner';

const MySubmissions = () => {
  const [activeTab, setActiveTab] = useState('content');
  const [statusFilter, setStatusFilter] = useState('all');

  const { data: contentData, isLoading: contentLoading } = useQuery(
    ['mySubmissions', 'content', statusFilter],
    () => axios.get(`/api/content/my-submissions?status=${statusFilter === 'all' ? '' : statusFilter}`).then(res => res.data),
    { refetchInterval: 30000 }
  );

  const { data: testsData, isLoading: testsLoading } = useQuery(
    ['mySubmissions', 'tests', statusFilter],
    () => axios.get(`/api/tests/my-submissions?status=${statusFilter === 'all' ? '' : statusFilter}`).then(res => res.data),
    { refetchInterval: 30000 }
  );

  const getStatusIcon = (status) => {
    switch (status) {
      case 'approved':
        return <CheckCircle className="h-5 w-5 text-green-500" />;
      case 'rejected':
        return <XCircle className="h-5 w-5 text-red-500" />;
      case 'pending':
        return <Clock className="h-5 w-5 text-yellow-500" />;
      default:
        return <AlertCircle className="h-5 w-5 text-gray-500" />;
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'approved':
        return 'bg-green-100 text-green-800';
      case 'rejected':
        return 'bg-red-100 text-red-800';
      case 'pending':
        return 'bg-yellow-100 text-yellow-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const tabs = [
    { id: 'content', label: 'Content', count: contentData?.pagination?.totalItems || 0 },
    { id: 'tests', label: 'Tests', count: testsData?.pagination?.totalItems || 0 }
  ];

  const statusOptions = [
    { value: 'all', label: 'All' },
    { value: 'pending', label: 'Pending' },
    { value: 'approved', label: 'Approved' },
    { value: 'rejected', label: 'Rejected' }
  ];

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-gray-900">My Submissions</h1>
          <p className="text-gray-600 mt-2">
            Track the status of your uploaded content and created tests.
          </p>
        </div>

        {/* Tabs */}
        <div className="bg-white rounded-lg shadow-sm mb-6">
          <div className="border-b border-gray-200">
            <nav className="flex space-x-8 px-6">
              {tabs.map((tab) => (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`py-4 px-1 border-b-2 font-medium text-sm ${
                    activeTab === tab.id
                      ? 'border-blue-500 text-blue-600'
                      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                  }`}
                >
                  {tab.label}
                  <span className="ml-2 bg-gray-100 text-gray-600 py-0.5 px-2 rounded-full text-xs">
                    {tab.count}
                  </span>
                </button>
              ))}
            </nav>
          </div>

          {/* Filters */}
          <div className="px-6 py-4 border-b border-gray-200">
            <div className="flex items-center space-x-4">
              <label className="text-sm font-medium text-gray-700">Filter by status:</label>
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                {statusOptions.map(option => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Content */}
          <div className="p-6">
            {activeTab === 'content' && (
              <div>
                <h2 className="text-xl font-semibold text-gray-900 mb-4">Content Submissions</h2>
                {contentLoading ? (
                  <LoadingSpinner />
                ) : contentData?.content?.length > 0 ? (
                  <div className="space-y-4">
                    {contentData.content.map((item) => (
                      <div key={item._id} className="border border-gray-200 rounded-lg p-4 hover:shadow-md transition-shadow">
                        <div className="flex items-start justify-between">
                          <div className="flex-1">
                            <div className="flex items-center mb-2">
                              <FileText className="h-5 w-5 text-gray-400 mr-3" />
                              <h3 className="text-lg font-medium text-gray-900">{item.title}</h3>
                              <span className={`ml-3 inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getStatusColor(item.status)}`}>
                                {getStatusIcon(item.status)}
                                <span className="ml-1 capitalize">{item.status}</span>
                              </span>
                            </div>
                            <p className="text-sm text-gray-600 mb-2">{item.description}</p>
                            <div className="flex items-center text-sm text-gray-500 space-x-4">
                              <span>Subject: {item.subject}</span>
                              <span>Type: {item.type}</span>
                              <span>Difficulty: {item.difficulty}</span>
                              <span>Submitted: {formatDate(item.createdAt)}</span>
                            </div>
                            {item.rejectionReason && (
                              <div className="mt-2 p-2 bg-red-50 border border-red-200 rounded text-sm text-red-700">
                                <strong>Rejection Reason:</strong> {item.rejectionReason}
                              </div>
                            )}
                          </div>
                          <div className="flex items-center space-x-2 ml-4">
                            <a
                              href={item.url}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="text-blue-600 hover:text-blue-800"
                            >
                              <ExternalLink className="h-4 w-4" />
                            </a>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-8">
                    <FileText className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                    <h3 className="text-lg font-medium text-gray-900 mb-2">No content submissions</h3>
                    <p className="text-gray-600">You haven't uploaded any content yet.</p>
                  </div>
                )}
              </div>
            )}

            {activeTab === 'tests' && (
              <div>
                <h2 className="text-xl font-semibold text-gray-900 mb-4">Test Submissions</h2>
                {testsLoading ? (
                  <LoadingSpinner />
                ) : testsData?.tests?.length > 0 ? (
                  <div className="space-y-4">
                    {testsData.tests.map((test) => (
                      <div key={test._id} className="border border-gray-200 rounded-lg p-4 hover:shadow-md transition-shadow">
                        <div className="flex items-start justify-between">
                          <div className="flex-1">
                            <div className="flex items-center mb-2">
                              <FileText className="h-5 w-5 text-gray-400 mr-3" />
                              <h3 className="text-lg font-medium text-gray-900">{test.title}</h3>
                              <span className={`ml-3 inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getStatusColor(test.status)}`}>
                                {getStatusIcon(test.status)}
                                <span className="ml-1 capitalize">{test.status}</span>
                              </span>
                            </div>
                            <p className="text-sm text-gray-600 mb-2">{test.description}</p>
                            <div className="flex items-center text-sm text-gray-500 space-x-4">
                              <span>Subject: {test.subject}</span>
                              <span>Questions: {test.questions.length}</span>
                              <span>Duration: {test.duration} min</span>
                              <span>Marks: {test.totalMarks}</span>
                              <span>Created: {formatDate(test.createdAt)}</span>
                            </div>
                            {test.rejectionReason && (
                              <div className="mt-2 p-2 bg-red-50 border border-red-200 rounded text-sm text-red-700">
                                <strong>Rejection Reason:</strong> {test.rejectionReason}
                              </div>
                            )}
                          </div>
                          <div className="flex items-center space-x-2 ml-4">
                            <button className="text-blue-600 hover:text-blue-800">
                              <Eye className="h-4 w-4" />
                            </button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-8">
                    <FileText className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                    <h3 className="text-lg font-medium text-gray-900 mb-2">No test submissions</h3>
                    <p className="text-gray-600">You haven't created any tests yet.</p>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default MySubmissions;
